import {
  createHash,
  randomBytes,
  scrypt as nodeScrypt,
  timingSafeEqual,
} from "node:crypto";
import { promisify } from "node:util";

const scrypt = promisify(nodeScrypt);

export interface AuthRequest {
  method: string;
  path: string;
  headers?: Record<string, string | undefined>;
  body?: unknown;
  remoteAddress?: string;
}

export interface AuthResponse {
  status: number;
  headers: Record<string, string>;
  body: string;
}

export interface AuthUser {
  id: string;
  email: string;
  passwordHash: string;
  createdAt: string;
}

export interface PublicUser {
  id: string;
  email: string;
  createdAt: string;
}

export interface UserStore {
  findByEmail(email: string): Promise<AuthUser | null>;
  findById(id: string): Promise<AuthUser | null>;
  create(email: string, passwordHash: string): Promise<AuthUser>;
}

export interface Session {
  id: string;
  userId: string;
  tokenHash: string;
  createdAt: number;
  expiresAt: number;
}

export interface AuthHandlerOptions {
  userStore?: UserStore;
  sessionTtlMs?: number;
  secureCookies?: boolean;
  cookieName?: string;
  maxBodyBytes?: number;
  ipRateLimit?: RateLimitOptions;
  accountRateLimit?: RateLimitOptions;
  now?: () => number;
}

export interface RateLimitOptions {
  limit: number;
  windowMs: number;
  maxKeys?: number;
}

interface RateBucket {
  timestamps: number[];
  lastAccess: number;
}

interface ParsedLogin {
  email: string;
  password: string;
}

const DEFAULT_SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const DEFAULT_MAX_BODY_BYTES = 16 * 1024;
const DEFAULT_COOKIE_NAME = "sid";
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/u;

function jsonResponse(
  status: number,
  payload: unknown,
  headers: Record<string, string> = {},
): AuthResponse {
  return {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      pragma: "no-cache",
      ...headers,
    },
    body: JSON.stringify(payload),
  };
}

function emptyResponse(
  status: number,
  headers: Record<string, string> = {},
): AuthResponse {
  return {
    status,
    headers: {
      "cache-control": "no-store",
      pragma: "no-cache",
      ...headers,
    },
    body: "",
  };
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

function publicUser(user: AuthUser): PublicUser {
  return {
    id: user.id,
    email: user.email,
    createdAt: user.createdAt,
  };
}

function hashToken(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

function safeEqualStrings(a: string, b: string): boolean {
  const left = Buffer.from(a, "utf8");
  const right = Buffer.from(b, "utf8");
  return left.length === right.length && timingSafeEqual(left, right);
}

function getHeader(
  request: AuthRequest,
  name: string,
): string | undefined {
  const headers = request.headers ?? {};
  const target = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === target) {
      return value;
    }
  }

  return undefined;
}

function parseCookies(value: string | undefined): Map<string, string> {
  const result = new Map<string, string>();

  if (!value) {
    return result;
  }

  for (const part of value.split(";")) {
    const separator = part.indexOf("=");

    if (separator <= 0) {
      continue;
    }

    const name = part.slice(0, separator).trim();
    const encodedValue = part.slice(separator + 1).trim();

    if (!name) {
      continue;
    }

    try {
      result.set(name, decodeURIComponent(encodedValue));
    } catch {
      result.set(name, encodedValue);
    }
  }

  return result;
}

function serializeCookie(
  name: string,
  value: string,
  options: {
    maxAge?: number;
    expires?: Date;
    httpOnly?: boolean;
    secure?: boolean;
    sameSite?: "Strict" | "Lax" | "None";
    path?: string;
  } = {},
): string {
  const segments = [
    `${name}=${encodeURIComponent(value)}`,
    `Path=${options.path ?? "/"}`,
  ];

  if (options.maxAge !== undefined) {
    segments.push(`Max-Age=${Math.max(0, Math.floor(options.maxAge))}`);
  }

  if (options.expires) {
    segments.push(`Expires=${options.expires.toUTCString()}`);
  }

  if (options.httpOnly !== false) {
    segments.push("HttpOnly");
  }

  if (options.secure !== false) {
    segments.push("Secure");
  }

  if (options.sameSite) {
    segments.push(`SameSite=${options.sameSite}`);
  }

  return segments.join("; ");
}

function parseRequestBody(
  body: unknown,
  maxBodyBytes: number,
): Record<string, unknown> | null {
  if (body === null || body === undefined) {
    return null;
  }

  let parsed: unknown = body;

  if (typeof body === "string") {
    if (Buffer.byteLength(body, "utf8") > maxBodyBytes) {
      throw new Error("body_too_large");
    }

    try {
      parsed = JSON.parse(body);
    } catch {
      throw new Error("invalid_json");
    }
  } else if (Buffer.isBuffer(body)) {
    if (body.byteLength > maxBodyBytes) {
      throw new Error("body_too_large");
    }

    try {
      parsed = JSON.parse(body.toString("utf8"));
    } catch {
      throw new Error("invalid_json");
    }
  } else if (typeof body === "object") {
    const serialized = JSON.stringify(body);

    if (Buffer.byteLength(serialized, "utf8") > maxBodyBytes) {
      throw new Error("body_too_large");
    }
  } else {
    throw new Error("invalid_json");
  }

  if (
    typeof parsed !== "object" ||
    parsed === null ||
    Array.isArray(parsed)
  ) {
    throw new Error("invalid_json");
  }

  return parsed as Record<string, unknown>;
}

function parseLogin(
  body: Record<string, unknown> | null,
): ParsedLogin | null {
  if (!body || typeof body.email !== "string" || typeof body.password !== "string") {
    return null;
  }

  const email = normalizeEmail(body.email);
  const password = body.password;

  if (
    !EMAIL_PATTERN.test(email) ||
    email.length > 320 ||
    password.length < 1 ||
    password.length > 1024
  ) {
    return null;
  }

  return { email, password };
}

export async function hashPassword(password: string): Promise<string> {
  if (typeof password !== "string" || password.length < 12 || password.length > 1024) {
    throw new Error("Password must contain between 12 and 1024 characters");
  }

  const salt = randomBytes(16);
  const derived = (await scrypt(password, salt, 64, {
    N: 16384,
    r: 8,
    p: 1,
    maxmem: 32 * 1024 * 1024,
  })) as Buffer;

  return [
    "scrypt",
    "16384",
    "8",
    "1",
    salt.toString("base64url"),
    derived.toString("base64url"),
  ].join("$");
}

export async function verifyPassword(
  password: string,
  encodedHash: string,
): Promise<boolean> {
  try {
    const parts = encodedHash.split("$");

    if (
      parts.length !== 6 ||
      parts[0] !== "scrypt" ||
      parts.slice(1, 4).some((value) => !/^\d+$/u.test(value))
    ) {
      return false;
    }

    const n = Number(parts[1]);
    const r = Number(parts[2]);
    const p = Number(parts[3]);
    const salt = Buffer.from(parts[4], "base64url");
    const expected = Buffer.from(parts[5], "base64url");

    if (
      !Number.isSafeInteger(n) ||
      !Number.isSafeInteger(r) ||
      !Number.isSafeInteger(p) ||
      n < 1024 ||
      n > 32768 ||
      r < 1 ||
      r > 32 ||
      p < 1 ||
      p > 8 ||
      salt.length < 16 ||
      expected.length !== 64
    ) {
      return false;
    }

    const actual = (await scrypt(password, salt, expected.length, {
      N: n,
      r,
      p,
      maxmem: 64 * 1024 * 1024,
    })) as Buffer;

    return timingSafeEqual(actual, expected);
  } catch {
    return false;
  }
}

export class MemoryUserStore implements UserStore {
  private readonly usersById = new Map<string, AuthUser>();
  private readonly idsByEmail = new Map<string, string>();

  async findByEmail(email: string): Promise<AuthUser | null> {
    const id = this.idsByEmail.get(normalizeEmail(email));

    if (!id) {
      return null;
    }

    return this.usersById.get(id) ?? null;
  }

  async findById(id: string): Promise<AuthUser | null> {
    return this.usersById.get(id) ?? null;
  }

  async create(email: string, passwordHash: string): Promise<AuthUser> {
    const normalizedEmail = normalizeEmail(email);

    if (!EMAIL_PATTERN.test(normalizedEmail) || normalizedEmail.length > 320) {
      throw new Error("invalid_email");
    }

    if (this.idsByEmail.has(normalizedEmail)) {
      throw new Error("email_exists");
    }

    const user: AuthUser = {
      id: randomBytes(16).toString("hex"),
      email: normalizedEmail,
      passwordHash,
      createdAt: new Date().toISOString(),
    };

    this.usersById.set(user.id, user);
    this.idsByEmail.set(normalizedEmail, user.id);
    return user;
  }
}

export class SlidingWindowRateLimiter {
  private readonly buckets = new Map<string, RateBucket>();
  private readonly limit: number;
  private readonly windowMs: number;
  private readonly maxKeys: number;
  private lastCleanup = 0;

  constructor(options: RateLimitOptions) {
    if (
      !Number.isInteger(options.limit) ||
      options.limit <= 0 ||
      !Number.isFinite(options.windowMs) ||
      options.windowMs <= 0
    ) {
      throw new Error("Invalid rate limiter configuration");
    }

    this.limit = options.limit;
    this.windowMs = options.windowMs;
    this.maxKeys = Math.max(100, Math.floor(options.maxKeys ?? 10000));
  }

  consume(key: string, now = Date.now()): {
    allowed: boolean;
    retryAfterSeconds: number;
  } {
    const normalizedKey = key.slice(0, 512);
    let bucket = this.buckets.get(normalizedKey);

    if (!bucket) {
      if (this.buckets.size >= this.maxKeys) {
        this.evictLeastRecentlyUsed();
      }

      bucket = { timestamps: [], lastAccess: now };
      this.buckets.set(normalizedKey, bucket);
    }

    const cutoff = now - this.windowMs;
    bucket.timestamps = bucket.timestamps.filter((timestamp) => timestamp > cutoff);
    bucket.lastAccess = now;

    if (bucket.timestamps.length >= this.limit) {
      const oldest = bucket.timestamps[0] ?? now;
      return {
        allowed: false,
        retryAfterSeconds: Math.max(
          1,
          Math.ceil((oldest + this.windowMs - now) / 1000),
        ),
      };
    }

    bucket.timestamps.push(now);

    if (now - this.lastCleanup > this.windowMs) {
      this.cleanup(now);
    }

    return { allowed: true, retryAfterSeconds: 0 };
  }

  reset(key: string): void {
    this.buckets.delete(key.slice(0, 512));
  }

  private cleanup(now: number): void {
    this.lastCleanup = now;
    const cutoff = now - this.windowMs;

    for (const [key, bucket] of this.buckets) {
      bucket.timestamps = bucket.timestamps.filter((timestamp) => timestamp > cutoff);

      if (bucket.timestamps.length === 0 && now - bucket.lastAccess > this.windowMs) {
        this.buckets.delete(key);
      }
    }
  }

  private evictLeastRecentlyUsed(): void {
    let candidate: string | undefined;
    let oldest = Number.POSITIVE_INFINITY;

    for (const [key, bucket] of this.buckets) {
      if (bucket.lastAccess < oldest) {
        oldest = bucket.lastAccess;
        candidate = key;
      }
    }

    if (candidate) {
      this.buckets.delete(candidate);
    }
  }
}

export class SessionManager {
  private readonly sessions = new Map<string, Session>();
  private readonly ttlMs: number;
  private readonly now: () => number;
  private lastCleanup = 0;

  constructor(ttlMs = DEFAULT_SESSION_TTL_MS, now = Date.now) {
    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
      throw new Error("Invalid session TTL");
    }

    this.ttlMs = ttlMs;
    this.now = now;
  }

  create(userId: string): { token: string; session: Session } {
    const token = randomBytes(32).toString("base64url");
    const current = this.now();
    const session: Session = {
      id: randomBytes(16).toString("hex"),
      userId,
      tokenHash: hashToken(token),
      createdAt: current,
      expiresAt: current + this.ttlMs,
    };

    this.sessions.set(session.tokenHash, session);
    this.cleanup(current);

    return { token, session };
  }

  get(token: string | undefined): Session | null {
    if (!token || token.length < 32 || token.length > 256) {
      return null;
    }

    const tokenHash = hashToken(token);
    const session = this.sessions.get(tokenHash);
    const current = this.now();

    if (!session || session.expiresAt <= current) {
      if (session) {
        this.sessions.delete(tokenHash);
      }
      return null;
    }

    return session;
  }

  revoke(token: string | undefined): void {
    if (token) {
      this.sessions.delete(hashToken(token));
    }
  }

  revokeUser(userId: string): void {
    for (const [tokenHash, session] of this.sessions) {
      if (session.userId === userId) {
        this.sessions.delete(tokenHash);
      }
    }
  }

  private cleanup(now: number): void {
    if (now - this.lastCleanup < 60_000) {
      return;
    }

    this.lastCleanup = now;

    for (const [tokenHash, session] of this.sessions) {
      if (session.expiresAt <= now) {
        this.sessions.delete(tokenHash);
      }
    }
  }
}

export class AuthenticationHandler {
  readonly userStore: UserStore;
  readonly sessions: SessionManager;

  private readonly ipLimiter: SlidingWindowRateLimiter;
  private readonly accountLimiter: SlidingWindowRateLimiter;
  private readonly maxBodyBytes: number;
  private readonly secureCookies: boolean;
  private readonly cookieName: string;
  private readonly now: () => number;
  private readonly dummyPasswordHashPromise: Promise<string>;

  constructor(options: AuthHandlerOptions = {}) {
    this.userStore = options.userStore ?? new MemoryUserStore();
    this.now = options.now ?? Date.now;
    this.sessions = new SessionManager(
      options.sessionTtlMs ?? DEFAULT_SESSION_TTL_MS,
      this.now,
    );
    this.ipLimiter = new SlidingWindowRateLimiter(
      options.ipRateLimit ?? {
        limit: 30,
        windowMs: 15 * 60 * 1000,
        maxKeys: 100_000,
      },
    );
    this.accountLimiter = new SlidingWindowRateLimiter(
      options.accountRateLimit ?? {
        limit: 10,
        windowMs: 15 * 60 * 1000,
        maxKeys: 100_000,
      },
    );
    this.maxBodyBytes = options.maxBodyBytes ?? DEFAULT_MAX_BODY_BYTES;
    this.secureCookies = options.secureCookies ?? true;
    this.cookieName = options.cookieName ?? DEFAULT_COOKIE_NAME;
    this.dummyPasswordHashPromise = hashPassword(
      "dummy-password-used-only-to-equalize-login-timing",
    );
  }

  async handle(request: AuthRequest): Promise<AuthResponse> {
    const method = request.method.toUpperCase();
    const path = request.path.split("?", 1)[0];

    if (method === "POST" && path === "/auth/login") {
      return this.login(request);
    }

    if (method === "POST" && path === "/auth/logout") {
      return this.logout(request);
    }

    if (method === "GET" && path === "/auth/me") {
      return this.me(request);
    }

    return jsonResponse(404, { error: "not_found" });
  }

  async register(email: string, password: string): Promise<PublicUser> {
    const normalizedEmail = normalizeEmail(email);

    if (!EMAIL_PATTERN.test(normalizedEmail) || normalizedEmail.length > 320) {
      throw new Error("invalid_email");
    }

    const passwordHash = await hashPassword(password);
    const user = await this.userStore.create(normalizedEmail, passwordHash);
    return publicUser(user);
  }

  private async login(request: AuthRequest): Promise<AuthResponse> {
    const ip = (request.remoteAddress ?? "unknown").slice(0, 128);
    const ipResult = this.ipLimiter.consume(`ip:${ip}`, this.now());

    if (!ipResult.allowed) {
      return jsonResponse(
        429,
        { error: "too_many_requests" },
        { "retry-after": String(ipResult.retryAfterSeconds) },
      );
    }

    let body: Record<string, unknown> | null;

    try {
      body = parseRequestBody(request.body, this.maxBodyBytes);
    } catch (error) {
      const code = error instanceof Error ? error.message : "invalid_json";

      return jsonResponse(
        code === "body_too_large" ? 413 : 400,
        { error: code === "body_too_large" ? "payload_too_large" : "invalid_request" },
      );
    }

    const credentials = parseLogin(body);

    if (!credentials) {
      return jsonResponse(400, { error: "invalid_request" });
    }

    const accountKey = `account:${credentials.email}`;
    const accountResult = this.accountLimiter.consume(accountKey, this.now());

    if (!accountResult.allowed) {
      return jsonResponse(
        429,
        { error: "too_many_requests" },
        { "retry-after": String(accountResult.retryAfterSeconds) },
      );
    }

    const user = await this.userStore.findByEmail(credentials.email);
    const passwordHash = user?.passwordHash ?? (await this.dummyPasswordHashPromise);
    const passwordValid = await verifyPassword(credentials.password, passwordHash);

    if (!user || !passwordValid) {
      return jsonResponse(401, { error: "invalid_credentials" });
    }

    this.accountLimiter.reset(accountKey);

    const { token } = this.sessions.create(user.id);
    const maxAge = Math.floor(
      (this.sessions["ttlMs"] as unknown as number) / 1000,
    );

    return jsonResponse(
      200,
      { user: publicUser(user) },
      {
        "set-cookie": serializeCookie(this.cookieName, token, {
          maxAge,
          httpOnly: true,
          secure: this.secureCookies,
          sameSite: "Strict",
          path: "/",
        }),
      },
    );
  }

  private async logout(request: AuthRequest): Promise<AuthResponse> {
    const cookies = parseCookies(getHeader(request, "cookie"));
    const token = cookies.get(this.cookieName);

    this.sessions.revoke(token);

    return emptyResponse(204, {
      "set-cookie": serializeCookie(this.cookieName, "", {
        maxAge: 0,
        expires: new Date(0),
        httpOnly: true,
        secure: this.secureCookies,
        sameSite: "Strict",
        path: "/",
      }),
    });
  }

  private async me(request: AuthRequest): Promise<AuthResponse> {
    const cookies = parseCookies(getHeader(request, "cookie"));
    const session = this.sessions.get(cookies.get(this.cookieName));

    if (!session) {
      return jsonResponse(401, { error: "unauthorized" });
    }

    const user = await this.userStore.findById(session.userId);

    if (!user) {
      this.sessions.revoke(cookies.get(this.cookieName));
      return jsonResponse(401, { error: "unauthorized" });
    }

    return jsonResponse(200, { user: publicUser(user) });
  }
}

export function createAuthenticationHandler(
  options: AuthHandlerOptions = {},
): AuthenticationHandler {
  return new AuthenticationHandler(options);
}

