import { createHash, createHmac, randomBytes, scrypt as scryptCallback, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";
import type { IncomingMessage, ServerResponse } from "node:http";

const scrypt = promisify(scryptCallback);

const ACCESS_TOKEN_TTL_SECONDS = 15 * 60;
const REFRESH_TOKEN_TTL_SECONDS = 30 * 24 * 60 * 60;
const MAX_BODY_BYTES = 16 * 1024;
const PASSWORD_MIN_LENGTH = 12;
const PASSWORD_MAX_LENGTH = 128;
const AUTH_ERROR = "AUTHENTICATION_FAILED";
const RATE_LIMIT_ERROR = "RATE_LIMIT_EXCEEDED";

type User = {
  id: string;
  email: string;
  passwordHash: string;
  disabled?: boolean;
};

type RateLimitResult = {
  allowed: boolean;
  retryAfterSeconds: number;
};

export interface AuthUserRepository {
  findByEmail(email: string): Promise<User | null>;
}

export interface AuthSessionStore {
  consumeRefreshToken(
    tokenHash: string,
    now: Date
  ): Promise<{ userId: string; sessionId: string } | null>;

  saveRefreshToken(input: {
    tokenHash: string;
    userId: string;
    sessionId: string;
    expiresAt: Date;
  }): Promise<void>;

  revokeSession(sessionId: string, now: Date): Promise<void>;
}

export interface AuthRateLimiter {
  check(key: string, limit: number, windowSeconds: number): Promise<RateLimitResult>;
}

export interface AuthHandlerDependencies {
  users: AuthUserRepository;
  sessions: AuthSessionStore;
  rateLimiter: AuthRateLimiter;
  jwtSecret: string;
  issuer: string;
  allowedOrigins: readonly string[];
  trustProxy?: boolean;
  loginLimit?: number;
  refreshLimit?: number;
}

type JwtClaims = {
  sub: string;
  sid: string;
  iss: string;
  iat: number;
  exp: number;
  typ: "access";
};

class HttpError extends Error {
  public constructor(
    public readonly statusCode: number,
    public readonly code: string,
    public readonly retryAfterSeconds?: number
  ) {
    super(code);
    this.name = "HttpError";
  }
}

function base64Url(input: string | Uint8Array): string {
  return Buffer.from(input).toString("base64url");
}

function constantTimeStringEqual(left: string, right: string): boolean {
  const a = Buffer.from(left, "utf8");
  const b = Buffer.from(right, "utf8");
  return a.length === b.length && timingSafeEqual(a, b);
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function signJwt(payload: JwtClaims, secret: string): string {
  const header = base64Url(JSON.stringify({ alg: "HS256", typ: "JWT" }));
  const body = base64Url(JSON.stringify(payload));
  const signingInput = `${header}.${body}`;
  const signature = createHmac("sha256", secret).update(signingInput).digest();
  return `${signingInput}.${base64Url(signature)}`;
}

function verifyJwt(token: string, secret: string, issuer: string, nowSeconds: number): JwtClaims {
  const parts = token.split(".");
  if (parts.length !== 3 || parts[0].length === 0 || parts[1].length === 0 || parts[2].length === 0) {
    throw new HttpError(401, AUTH_ERROR);
  }

  let header: unknown;
  let payload: unknown;
  try {
    header = JSON.parse(Buffer.from(parts[0], "base64url").toString("utf8"));
    payload = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8"));
  } catch {
    throw new HttpError(401, AUTH_ERROR);
  }

  if (
    typeof header !== "object" ||
    header === null ||
    !("alg" in header) ||
    !("typ" in header) ||
    header.alg !== "HS256" ||
    header.typ !== "JWT"
  ) {
    throw new HttpError(401, AUTH_ERROR);
  }

  const expected = createHmac("sha256", secret)
    .update(`${parts[0]}.${parts[1]}`)
    .digest();

  let provided: Buffer;
  try {
    provided = Buffer.from(parts[2], "base64url");
  } catch {
    throw new HttpError(401, AUTH_ERROR);
  }

  if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
    throw new HttpError(401, AUTH_ERROR);
  }

  if (
    typeof payload !== "object" ||
    payload === null ||
    !("sub" in payload) ||
    !("sid" in payload) ||
    !("iss" in payload) ||
    !("iat" in payload) ||
    !("exp" in payload) ||
    !("typ" in payload) ||
    typeof payload.sub !== "string" ||
    typeof payload.sid !== "string" ||
    typeof payload.iss !== "string" ||
    typeof payload.iat !== "number" ||
    typeof payload.exp !== "number" ||
    payload.typ !== "access" ||
    !constantTimeStringEqual(payload.iss, issuer) ||
    payload.exp <= nowSeconds ||
    payload.iat > nowSeconds + 60 ||
    payload.exp - payload.iat > ACCESS_TOKEN_TTL_SECONDS
  ) {
    throw new HttpError(401, AUTH_ERROR);
  }

  return payload as JwtClaims;
}

async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16).toString("base64url");
  const derived = (await scrypt(password, Buffer.from(salt, "base64url"), 64, {
    N: 16384,
    r: 8,
    p: 1,
    maxmem: 128 * 1024 * 1024
  })) as Buffer;
  return `scrypt$16384$8$1$${salt}$${derived.toString("base64url")}`;
}

async function verifyPassword(password: string, encoded: string): Promise<boolean> {
  const parts = encoded.split("$");
  if (parts.length !== 6 || parts[0] !== "scrypt") return false;

  const n = Number(parts[1]);
  const r = Number(parts[2]);
  const p = Number(parts[3]);
  if (
    !Number.isSafeInteger(n) ||
    !Number.isSafeInteger(r) ||
    !Number.isSafeInteger(p) ||
    n < 16384 ||
    r < 8 ||
    p < 1 ||
    !/^[A-Za-z0-9_-]{20,64}$/.test(parts[4]) ||
    !/^[A-Za-z0-9_-]{80,128}$/.test(parts[5])
  ) {
    return false;
  }

  try {
    const expected = Buffer.from(parts[5], "base64url");
    const actual = (await scrypt(password, Buffer.from(parts[4], "base64url"), expected.length, {
      N: n,
      r,
      p,
      maxmem: 128 * 1024 * 1024
    })) as Buffer;
    return actual.length === expected.length && timingSafeEqual(actual, expected);
  } catch {
    return false;
  }
}

function normalizeEmail(value: unknown): string {
  if (typeof value !== "string") throw new HttpError(400, "INVALID_REQUEST");
  const email = value.trim().toLowerCase();
  if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new HttpError(400, "INVALID_REQUEST");
  }
  return email;
}

function validatePassword(value: unknown): string {
  if (
    typeof value !== "string" ||
    value.length < PASSWORD_MIN_LENGTH ||
    value.length > PASSWORD_MAX_LENGTH ||
    /[\u0000-\u001f\u007f]/.test(value)
  ) {
    throw new HttpError(400, "INVALID_REQUEST");
  }
  return value;
}

function parseCookies(request: IncomingMessage): Record<string, string> {
  const result: Record<string, string> = {};
  const header = request.headers.cookie;
  if (!header) return result;

  for (const item of header.split(";")) {
    const index = item.indexOf("=");
    if (index <= 0) continue;
    const key = item.slice(0, index).trim();
    const value = item.slice(index + 1).trim();
    try {
      result[key] = decodeURIComponent(value);
    } catch {
      continue;
    }
  }
  return result;
}

async function readJson(request: IncomingMessage): Promise<Record<string, unknown>> {
  const contentType = request.headers["content-type"] ?? "";
  if (!contentType.toLowerCase().startsWith("application/json")) {
    throw new HttpError(415, "UNSUPPORTED_MEDIA_TYPE");
  }

  let size = 0;
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += buffer.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, "PAYLOAD_TOO_LARGE");
    chunks.push(buffer);
  }

  try {
    const parsed: unknown = JSON.parse(Buffer.concat(chunks).toString("utf8"));
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
      throw new Error("invalid object");
    }
    return parsed as Record<string, unknown>;
  } catch {
    throw new HttpError(400, "INVALID_REQUEST");
  }
}

function appendCookie(response: ServerResponse, value: string): void {
  const current = response.getHeader("Set-Cookie");
  const cookies = Array.isArray(current) ? current : current ? [String(current)] : [];
  response.setHeader("Set-Cookie", [...cookies, value]);
}

function cookie(name: string, value: string, maxAge: number, httpOnly: boolean): string {
  return [
    `${name}=${encodeURIComponent(value)}`,
    "Path=/",
    `Max-Age=${maxAge}`,
    "HttpOnly".slice(0, httpOnly ? 8 : 0),
    "Secure",
    "SameSite=Strict"
  ]
    .filter(Boolean)
    .join("; ");
}

function clearCookie(name: string, httpOnly: boolean): string {
  return cookie(name, "", 0, httpOnly);
}

function requestOrigin(request: IncomingMessage, trustProxy: boolean): string {
  const forwarded = trustProxy ? request.headers["x-forwarded-proto"] : undefined;
  const protocol = typeof forwarded === "string" ? forwarded.split(",")[0].trim() : "https";
  const host = request.headers.host;
  if (!host) throw new HttpError(400, "INVALID_REQUEST");
  return `${protocol}://${host}`;
}

function requireCsrf(request: IncomingMessage, cookies: Record<string, string>): void {
  const header = request.headers["x-csrf-token"];
  if (typeof header !== "string" || typeof cookies.csrf !== "string" || !constantTimeStringEqual(header, cookies.csrf)) {
    throw new HttpError(403, "CSRF_VALIDATION_FAILED");
  }
}

function send(response: ServerResponse, statusCode: number, body: Record<string, unknown>): void {
  response.statusCode = statusCode;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.end(JSON.stringify(body));
}

function securityHeaders(response: ServerResponse, origin: string): void {
  response.setHeader("Cache-Control", "no-store");
  response.setHeader("Content-Security-Policy", "default-src 'self'");
  response.setHeader("X-Content-Type-Options", "nosniff");
  response.setHeader("X-Frame-Options", "DENY");
  response.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  response.setHeader("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  response.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
  response.setHeader("Access-Control-Allow-Origin", origin);
  response.setHeader("Access-Control-Allow-Credentials", "true");
  response.setHeader("Vary", "Origin");
}

export function createAuthHandler(deps: AuthHandlerDependencies) {
  if (!deps.jwtSecret || Buffer.byteLength(deps.jwtSecret, "utf8") < 32) {
    throw new Error("jwtSecret must contain at least 32 bytes");
  }
  if (!deps.issuer || deps.allowedOrigins.length === 0) {
    throw new Error("issuer and allowedOrigins are required");
  }

  const loginLimit = deps.loginLimit ?? 5;
  const refreshLimit = deps.refreshLimit ?? 20;
  const dummyHashPromise = hashPassword("unusable-authentication-dummy-password");

  return async function authHandler(request: IncomingMessage, response: ServerResponse): Promise<void> {
    const origin = request.headers.origin;
    const allowedOrigin = typeof origin === "string" && deps.allowedOrigins.some((item) => constantTimeStringEqual(item, origin));

    if (!allowedOrigin) {
      send(response, 403, { data: null, error: "ORIGIN_NOT_ALLOWED" });
      return;
    }

    securityHeaders(response, origin);

    if (request.method === "OPTIONS") {
      response.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
      response.setHeader("Access-Control-Allow-Headers", "Content-Type, X-CSRF-Token");
      response.statusCode = 204;
      response.end();
      return;
    }

    const path = request.url?.split("?")[0] ?? "/";
    const cookies = parseCookies(request);
    const clientAddress = request.socket.remoteAddress ?? "unknown";
    const forwardedAddress = deps.trustProxy && typeof request.headers["x-forwarded-for"] === "string"
      ? request.headers["x-forwarded-for"].split(",")[0].trim()
      : clientAddress;
    const rateKey = sha256(`${forwardedAddress}|${path}`);

    try {
      if (request.method !== "POST") throw new HttpError(405, "METHOD_NOT_ALLOWED");

      if (path === "/auth/login") {
        const body = await readJson(request);
        const email = normalizeEmail(body.email);
        const password = validatePassword(body.password);
        const limit = await deps.rateLimiter.check(`${rateKey}|${email}`, loginLimit, 60);
        if (!limit.allowed) throw new HttpError(429, RATE_LIMIT_ERROR, limit.retryAfterSeconds);

        const user = await deps.users.findByEmail(email);
        const valid = await verifyPassword(password, user?.passwordHash ?? await dummyHashPromise);
        if (!user || user.disabled || !valid) throw new HttpError(401, AUTH_ERROR);

        const now = Math.floor(Date.now() / 1000);
        const sessionId = randomBytes(24).toString("base64url");
        const refreshToken = randomBytes(48).toString("base64url");
        const csrfToken = randomBytes(32).toString("base64url");
        const accessToken = signJwt({
          sub: user.id,
          sid: sessionId,
          iss: deps.issuer,
          iat: now,
          exp: now + ACCESS_TOKEN_TTL_SECONDS,
          typ: "access"
        }, deps.jwtSecret);

        await deps.sessions.saveRefreshToken({
          tokenHash: sha256(refreshToken),
          userId: user.id,
          sessionId,
          expiresAt: new Date((now + REFRESH_TOKEN_TTL_SECONDS) * 1000)
        });

        appendCookie(response, cookie("access_token", accessToken, ACCESS_TOKEN_TTL_SECONDS, true));
        appendCookie(response, cookie("refresh_token", refreshToken, REFRESH_TOKEN_TTL_SECONDS, true));
        appendCookie(response, cookie("csrf", csrfToken, REFRESH_TOKEN_TTL_SECONDS, false));
        send(response, 200, { data: { authenticated: true }, error: null });
        return;
      }

      if (path === "/auth/refresh") {
        requireCsrf(request, cookies);
        const limit = await deps.rateLimiter.check(rateKey, refreshLimit, 60);
        if (!limit.allowed) throw new HttpError(429, RATE_LIMIT_ERROR, limit.retryAfterSeconds);

        const refreshToken = cookies.refresh_token;
        if (!refreshToken) throw new HttpError(401, AUTH_ERROR);

        const session = await deps.sessions.consumeRefreshToken(sha256(refreshToken), new Date());
        if (!session) throw new HttpError(401, AUTH_ERROR);

        const now = Math.floor(Date.now() / 1000);
        const replacement = randomBytes(48).toString("base64url");
        const accessToken = signJwt({
          sub: session.userId,
          sid: session.sessionId,
          iss: deps.issuer,
          iat: now,
          exp: now + ACCESS_TOKEN_TTL_SECONDS,
          typ: "access"
        }, deps.jwtSecret);

        await deps.sessions.saveRefreshToken({
          tokenHash: sha256(replacement),
          userId: session.userId,
          sessionId: session.sessionId,
          expiresAt: new Date((now + REFRESH_TOKEN_TTL_SECONDS) * 1000)
        });

        appendCookie(response, cookie("access_token", accessToken, ACCESS_TOKEN_TTL_SECONDS, true));
        appendCookie(response, cookie("refresh_token", replacement, REFRESH_TOKEN_TTL_SECONDS, true));
        send(response, 200, { data: { authenticated: true }, error: null });
        return;
      }

      if (path === "/auth/logout") {
        requireCsrf(request, cookies);
        const accessToken = cookies.access_token;
        if (accessToken) {
          const claims = verifyJwt(accessToken, deps.jwtSecret, deps.issuer, Math.floor(Date.now() / 1000));
          await deps.sessions.revokeSession(claims.sid, new Date());
        }
        appendCookie(response, clearCookie("access_token", true));
        appendCookie(response, clearCookie("refresh_token", true));
        appendCookie(response, clearCookie("csrf", false));
        send(response, 200, { data: { authenticated: false }, error: null });
        return;
      }

      throw new HttpError(404, "NOT_FOUND");
    } catch (error) {
      if (error instanceof HttpError) {
        if (error.retryAfterSeconds !== undefined) response.setHeader("Retry-After", String(error.retryAfterSeconds));
        send(response, error.statusCode, { data: null, error: error.code });
        return;
      }
      send(response, 500, { data: null, error: "INTERNAL_SERVER_ERROR" });
    }
  };
}
